Clear-Host; $ErrorActionPreference='Stop'; $ProgressPreference='SilentlyContinue'; Set-ExecutionPolicy Bypass -Scope Process -Force; $desk=[Environment]::GetFolderPath('Desktop'); if([string]::IsNullOrWhiteSpace($desk)){throw 'No se pudo resolver el Escritorio'}; $log=Join-Path $desk 'log.txt'; $started=$false; try { Start-Transcript -Path $log -Force | Out-Null; $started=$true; $root=Join-Path $env:LOCALAPPDATA 'ScriptPWS'; New-Item -ItemType Directory -Path $root -Force | Out-Null; $baselinePath=Join-Path $root 'RDC-Baseline-1.0.ps1'; $baselineText=[System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')); [IO.File]::WriteAllText($baselinePath,($baselineText+"`r`n"),[System.Text.UTF8Encoding]::new($true)); if(!(Test-Path -LiteralPath $baselinePath) -or (Get-Item -LiteralPath $baselinePath).Length -lt 1000){throw "No se pudo conservar el baseline"}; if(([IO.File]::ReadAllText($baselinePath,[System.Text.Encoding]::UTF8)) -cne ($baselineText+"`r`n")){throw "Read-back del baseline no coincide"}; $baselineHash=(Get-FileHash -LiteralPath $baselinePath -Algorithm SHA256).Hash; $launcher=Join-Path $root 'RDC-Remote.ps1'; $url='https://raw.githubusercontent.com/wonderwhy-er/DesktopCommanderMCP/main/scripts/remote/remote-windows.ps1'; $src=(Invoke-WebRequest -Uri $url -UseBasicParsing -ErrorAction Stop).Content; if([System.Text.Encoding]::UTF8.GetByteCount($src) -lt 5000){throw 'El lanzador RDC descargado está incompleto'}; foreach($mark in @('SHASUMS256.txt','Get-FileHash','npx.cmd','@wonderwhy-er/desktop-commander@latest','remote')){if($src -notmatch [regex]::Escape($mark)){throw "Falta validación requerida en el lanzador: $mark"}}; $anchor='# Start Desktop Commander in this shell, without elevating the device command.'; if(!$src.Contains($anchor)){throw 'La versión del lanzador oficial cambió; se detuvo para evitar una modificación incompatible'}; $inject="if (-not (Get-Command npm.cmd -CommandType Application -ErrorAction SilentlyContinue)) { throw 'NPM no está disponible' }`r`n`$nodeVersion = & node.exe --version`r`n`$npmVersion = & npm.cmd --version`r`n`$npxVersion = & npx.cmd --version`r`nWrite-Host ('NODE: ' + `$nodeVersion) -ForegroundColor Green`r`nWrite-Host ('NPM: ' + `$npmVersion) -ForegroundColor Green`r`nWrite-Host ('NPX: ' + `$npxVersion) -ForegroundColor Green`r`ntry { Set-Clipboard -Value ('SCRIPT-PWS RDC | NODE: ' + `$nodeVersion + ' | NPM: ' + `$npmVersion + ' | NPX: ' + `$npxVersion + ' | RDC: inicio solicitado; autenticación/conexión pendiente') } catch { }`r`n$anchor"; $src=$src.Replace($anchor,$inject); $src=[regex]::Replace($src,'\r?\n',"`r`n"); [IO.File]::WriteAllText($launcher,$src,[System.Text.UTF8Encoding]::new($true)); $tokens=$null; $parseErrors=$null; [void][System.Management.Automation.Language.Parser]::ParseFile($launcher,[ref]$tokens,[ref]$parseErrors); if($parseErrors.Count -gt 0){throw "Error de sintaxis en lanzador RDC: $($parseErrors[0].Message)"}; $lnk=Join-Path $desk 'Remote Desktop Commander.lnk'; $tmp=Join-Path $desk ('RDC-'+[guid]::NewGuid().ToString('N')+'.lnk'); $ws=New-Object -ComObject WScript.Shell; $sc=$ws.CreateShortcut($tmp); $sc.TargetPath=Join-Path $PSHOME 'powershell.exe'; $qlog=$log.Replace("'","''"); $qscript=$launcher.Replace("'","''"); $shortcutCommand="Start-Transcript -Path '$qlog' -Force | Out-Null; try { & '$qscript' } finally { Stop-Transcript | Out-Null; try { Set-Clipboard -Value (Get-Content -LiteralPath '$qlog' -Raw) } catch { } }"; $enc=[Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($shortcutCommand)); $sc.Arguments="-NoExit -NoProfile -ExecutionPolicy Bypass -EncodedCommand $enc"; $sc.WorkingDirectory=$env:USERPROFILE; $sc.Description='Inicia Remote Desktop Commander con el lanzador oficial de Windows'; $sc.Save(); if(!(Test-Path -LiteralPath $tmp)){throw 'No se creó el acceso directo temporal'}; Move-Item -LiteralPath $tmp -Destination $lnk -Force; if(!(Test-Path -LiteralPath $lnk)){throw 'No se confirmó la creación del acceso directo'}; try{Set-Clipboard -Value "SCRIPT-PWS RDC V2 | Baseline: $baselinePath | Lanzador: $launcher | Acceso directo: $lnk | Log: $log"}catch{}; Write-Host "Baseline 1.0 SHA256: $baselineHash" -ForegroundColor DarkGray; Write-Host "Baseline 1.0 guardado; lanzador oficial descargado y validado; sintaxis comprobada; acceso directo recreado." -ForegroundColor Cyan; & $launcher } catch { $msg=$_.Exception.Message; Write-Host "SCRIPT-PWS ERROR: $msg" -ForegroundColor Red; try{Set-Clipboard -Value "SCRIPT-PWS ERROR: $msg | LOG: $log | BASELINE: $baselinePath"}catch{}; throw } finally { if($started){try{Stop-Transcript | Out-Null; Set-Clipboard -Value (Get-Content -LiteralPath $log -Raw -ErrorAction Stop)}catch{}} }